"use client"

import * as React from "react"
import { Slot } from "@radix-ui/react-slot"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetSpine, SheetTitle, SheetTrigger } from "@/components/ui/sheet"

/** The width at which the words fit beside the work. It is also in sidebar.css: a media query can't read a variable. */
const BREAKPOINT = 860
const WIDE = `(min-width: ${BREAKPOINT}px)`

/** true once the window is wide; null until the browser has said (the server and the first paint show both surfaces and let CSS choose). */
function useWide() {
  return React.useSyncExternalStore<boolean | null>(
    (notify) => {
      const query = matchMedia(WIDE)
      query.addEventListener("change", notify)
      return () => query.removeEventListener("change", notify)
    },
    () => matchMedia(WIDE).matches,
    () => null,
  )
}

/** Set a word large and light by its first letter, so folding leaves only that. Anything that isn't plain text is left alone. */
function fold(node: React.ReactNode): React.ReactNode {
  if (typeof node !== "string" || node.length < 2) return node
  const [first, ...rest] = Array.from(node)
  return (
    <>
      <span className="db-sidebar-i">{first}</span>
      <span className="db-sidebar-rest">{rest.join("")}</span>
    </>
  )
}

type SidebarProps = Omit<React.ComponentProps<"nav">, "aria-label"> & {
  /** Names the landmark: "Studio app", "Docs". */
  label: string
  /** The trigger's word, and the sheet's name, when the window is too narrow for the column. */
  sheetLabel?: string
  /** Each word keeps only its initial, set large and light; the rest folds away in turn. */
  folded?: boolean
  /** Smaller words, closer together: for a long index. */
  compact?: boolean
}

/**
 * A column of words beside the work. Wide, it stands inline; narrow, only a quiet trigger shows
 * and the same words open in a sheet. Choosing a link in the sheet puts it away.
 */
function Sidebar({ label, sheetLabel = "Index", folded, compact, className, children, ...props }: SidebarProps) {
  const wide = useWide()
  const [open, setOpen] = React.useState(false)
  // Widening puts the sheet away, so it isn't waiting open when the window narrows again.
  const [was, setWas] = React.useState(wide)
  if (wide !== was) {
    setWas(wide)
    if (wide) setOpen(false)
  }

  return (
    <nav data-slot="sidebar" aria-label={label} className={cn("db-sidebar", className)} {...props}>
      {wide !== false && (
        <div data-slot="sidebar-list" data-folded={folded || undefined} data-compact={compact || undefined} className="db-sidebar-list">
          {children}
        </div>
      )}
      <Sheet open={open} onOpenChange={setOpen}>
        {wide !== true && (
          <SheetTrigger asChild>
            <Button variant="quiet" data-slot="sidebar-trigger">{sheetLabel}</Button>
          </SheetTrigger>
        )}
        {wide === false && (
          <SheetContent side="start" className="db-sidebar-sheet">
            <SheetSpine>{sheetLabel}</SheetSpine>
            <SheetTitle className="db-sr">{sheetLabel}</SheetTitle>
            <div
              data-slot="sidebar-list"
              data-compact={compact || undefined}
              className="db-sidebar-list"
              onClick={(e) => {
                if ((e.target as Element).closest("a[href]")) setOpen(false)
              }}
            >
              {children}
            </div>
          </SheetContent>
        )}
      </Sheet>
    </nav>
  )
}

/** The column's own name, at the top. Folded, it too keeps its initial. */
function SidebarHead({ className, children, ...props }: React.ComponentProps<"p">) {
  return (
    <p data-slot="sidebar-head" className={cn("db-sidebar-head", className)} {...props}>
      {fold(children)}
    </p>
  )
}

type SidebarGroupProps = Omit<React.ComponentProps<"div">, "aria-labelledby"> & {
  /** What the links share: a movement ("VI Controls"), a section. */
  label: string
}

function SidebarGroup({ label, className, children, ...props }: SidebarGroupProps) {
  const id = React.useId()
  return (
    <div data-slot="sidebar-group" className={cn("db-sidebar-group", className)} {...props}>
      <p id={id} data-slot="sidebar-label" className="db-sidebar-label">{label}</p>
      <ul aria-labelledby={id} className="db-sidebar-links">{children}</ul>
    </div>
  )
}

type SidebarLinkProps = React.ComponentProps<"a"> & {
  /** The page you are on: it carries the accent dot. */
  current?: boolean
  /** Render the child (a framework's Link) with the sidebar's look. */
  asChild?: boolean
}

function SidebarLink({ current, asChild = false, className, children, ...props }: SidebarLinkProps) {
  const Comp = asChild ? Slot : "a"
  // A Slot's child carries the label, so fold that instead.
  const label = asChild && React.isValidElement<{ children?: React.ReactNode }>(children) ? React.cloneElement(children, undefined, fold(children.props.children)) : fold(children)
  return (
    <li data-slot="sidebar-item" className="db-sidebar-item">
      <Comp data-slot="sidebar-link" aria-current={current ? "page" : undefined} className={cn("db-sidebar-link", className)} {...props}>
        {label}
      </Comp>
    </li>
  )
}

export { Sidebar, SidebarHead, SidebarGroup, SidebarLink, type SidebarProps }

@layer components {
  /* ── db-sidebar ── a column of words; folded, each keeps only its initial.
     Wide, the words stand inline. Narrow, only the trigger shows and the same words open in a sheet.
     860px is the docs frame's breakpoint and BREAKPOINT in sidebar.tsx: keep them equal. */
  /* Registered, so each link's place is worked out on the link and inherited by its words. */
  @property --db-sidebar-i { syntax: "<integer>"; inherits: true; initial-value: 0; }
  .db-sidebar { font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-sidebar-list {
    display: grid; align-content: start; justify-items: start; gap: var(--db-space-1);
    font-size: var(--db-mp); line-height: var(--db-mp-lh);
  }
  /* Compact: a size down, and the links close up. */
  .db-sidebar-list[data-compact] { font-size: var(--db-p); line-height: var(--db-p-lh); }
  .db-sidebar-list[data-compact] :is(.db-sidebar-group, .db-sidebar-links) { gap: 0; }
  .db-sidebar-list[data-compact] :is(.db-sidebar-group + .db-sidebar-group, .db-sidebar-head + .db-sidebar-group) { margin-block-start: var(--db-space-5); }
  .db-sidebar > .db-sidebar-list { padding-inline-end: var(--db-space-6); border-inline-end: var(--db-hairline) solid var(--db-rule); }
  /* Before the browser has said how wide it is, both surfaces are in the page and CSS chooses. */
  @media (min-width: 860px) { .db-sidebar > [data-slot="sidebar-trigger"] { display: none; } }
  @media (max-width: 859.98px) { .db-sidebar > .db-sidebar-list { display: none; } }
  .db-sheet.db-sidebar-sheet { width: min(20rem, calc(100vw - var(--db-space-6))); }

  .db-sidebar-head { margin-block-end: var(--db-space-4); font-weight: 600; color: var(--db-ink); white-space: nowrap; }
  .db-sidebar-group { display: grid; justify-items: start; gap: var(--db-space-1); }
  .db-sidebar-group + .db-sidebar-group, .db-sidebar-head + .db-sidebar-group { margin-block-start: var(--db-space-4); }
  .db-sidebar-label {
    font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); white-space: nowrap;
    overflow: clip; height: auto;
    transition: height var(--db-andante) var(--db-exhale), margin var(--db-andante) var(--db-exhale), opacity var(--db-allegro);
  }
  .db-sidebar-links { display: grid; justify-items: start; gap: var(--db-space-1); margin: 0; padding: 0; list-style: none; }
  .db-sidebar-item { --db-sidebar-i: sibling-index(); }
  .db-sidebar-link {
    position: relative; display: flex; align-items: baseline; padding-inline-start: 1em;
    color: var(--db-graphite); text-decoration: none; white-space: nowrap; transition: color var(--db-allegro);
  }
  .db-sidebar-link:is(:hover, [data-force~="hover"]), .db-sidebar-link[aria-current="page"] { color: var(--db-ink); }
  .db-sidebar-link::before {
    content: ""; position: absolute; inset-inline-start: 0; top: calc(50% - 3px); width: 6px; height: 6px; border-radius: 50%;
    background: var(--db-accent); scale: 0;
    transition: scale var(--db-moderato) var(--db-spiccato), background-color var(--db-allegro), box-shadow var(--db-allegro);
  }
  .db-sidebar-link:is(:hover, [data-force~="hover"]):not([aria-current="page"])::before { scale: 1; background-color: transparent; box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong); }
  .db-sidebar-link[aria-current="page"]::before { scale: 1; }

  /* The initial stays; the rest folds away in turn. */
  .db-sidebar-i { font-weight: inherit; transition: font-size var(--db-andante) var(--db-exhale), font-weight var(--db-andante) var(--db-exhale); transition-delay: calc(var(--db-sidebar-i) * var(--db-arpeggio)); }
  .db-sidebar-rest { display: inline-block; overflow: clip; width: auto; transition: width var(--db-andante) var(--db-exhale), opacity var(--db-moderato); transition-delay: calc(var(--db-sidebar-i) * var(--db-arpeggio)); }
  .db-sidebar-list[data-folded] .db-sidebar-rest { width: 0; opacity: 0; }
  .db-sidebar-list[data-folded] .db-sidebar-i { font-size: 1.45em; font-weight: 200; }
  .db-sidebar-list[data-folded] .db-sidebar-label { height: 0; margin-block-start: var(--db-space-2); opacity: 0; }
}
